    let identity = self.context.identity().clone();
    let closing =
        crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop::new(&gate);
    let mut slot_closing = CloseOnDrop::new(&slot);
    async move {
        gate.require_open().map_err(|error| {
            AgentdError::GenerationFenced(error.to_string())
        })?;
        if state.identity() != &identity || cancellation.is_cancelled() {
            return Err(AgentdError::GenerationFenced(
                "original C retirement worker identity or cancellation differs".into(),
            ));
        }
        // The separately captured guards now own failure closure. The
