            return Err(AgentdError::GenerationFenced(
                "original C worker returned during fault cancellation".into(),
            ));
        }
        let joined = slot.finish_original_retirement_join(&identity, &gate, closing)?;
        slot_closing.disarm();
        Ok(joined)
    }
