/// Observe the same handle without requesting stop or closing Gate. The
/// caller retains the real C/learning terminal bundle and awaits the
/// original run_with_shutdown result before invoking this operation.
fn observe_original_natural_join<'a>(
    self: &'a Arc<Self>,
    original_c: &'a crate::circuit_task::OriginalSameActorCJoined,
) -> impl Future<Output = Result<OriginalCircuitNaturalJoin, AgentdError>> + Send + 'a {
    let closing =
        crate::same_actor_q24_phase_gate::CloseSameActorPhaseOnDrop::new(&self.gate);
    async move {
        crate::circuit_task::OriginalSameActorCJoined::require_original_phase(
            original_c,
            &self.identity,
            &self.gate,
        )?;
        let job = {
            let state = self.start.lock().map_err(custody_error)?;
            if state.stopped {
                return Err(custody_error("fault-stopped Circuit cannot retire normally"));
            }
            state.job.as_ref().cloned().ok_or_else(|| {
                custody_error("normal Circuit retirement has no actual started owner")
            })?
        };
        job.join_original_returned_ok().await?;
        crate::circuit_task::OriginalSameActorCJoined::require_original_phase(
            original_c,
            &self.identity,
            &self.gate,
        )?;
        if job.delivery.load(Ordering::Acquire) != RUNTIME_DELIVERED {
            return Err(custody_error("original Runtime has not received the Circuit result"));
        }
        Ok(OriginalCircuitNaturalJoin {
            identity: self.identity.clone(),
            gate: Arc::clone(&self.gate),
            job,
            _closing: closing,
            _custody: Arc::clone(self),
        })
    }
}

